mapper.select:
SELECT family_id, user_id, family_name, relation, birth_date
FROM family
WHERE family_id = #{familyId}

SELECT deduction_limit_id, relation, is_minor, deduction_limit, effective_from, effective_to
FROM gift_deduction_limit
WHERE relation = #{relation}
  AND is_minor = #{minor}
  AND effective_from <= #{asOfDate}
  AND (effective_to IS NULL OR effective_to > #{asOfDate})
ORDER BY effective_from DESC
LIMIT 1

SELECT gift_id, amount, gift_date
FROM gift
WHERE family_id = #{familyId}
  AND status = 'COMPLETED'
  AND gift_date >= #{windowStart}
  AND gift_date < #{asOfDate}
ORDER BY gift_date, gift_id

mapper.insert:
INSERT INTO simulation_result (
    simul_id, scenario_type, deduction_amount, taxable_amount, gift_tax,
    donor_required_amount, post_tax_amount, investment_principal, created_at
) VALUES (
    #{simulationId}, #{scenarioType}, #{deductionAmount}, #{taxableAmount},
    #{giftTax}, #{donorRequiredAmount}, #{postTaxAmount},
    #{investmentPrincipal}, #{createdAt}
)

INSERT INTO simulation_portfolio (
    simul_result_id, portfolio_type, deposit_amount, savings_amount,
    etf_amount, expected_future_value, is_recommended, created_at, updated_at
) VALUES (
    #{resultId}, #{portfolioType}, #{depositAmount}, #{savingsAmount},
    #{etfAmount}, #{expectedFutureValue}, #{recommended}, #{createdAt}, #{updatedAt}
)

mapper.update:
UPDATE simulation_portfolio
SET is_recommended = 1, updated_at = NOW()
WHERE simul_portfolio_id = #{portfolioId}

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM simulation_product spr
    JOIN simulation_portfolio sp ON sp.simul_portfolio_id = spr.simul_portfolio_id
    JOIN simulation_result sr ON sr.simul_result_id = sp.simul_result_id
    WHERE sr.simul_id = #{simulationId}
      AND spr.kb_product_version_id = #{productVersionId}
)

SELECT preferential_interest_rate_id, kb_product_version_id AS product_version_id, additional_rate_percent, condition_code, preferential_condition AS description FROM preferential_interest_rate WHERE kb_product_version_id = #{productVersionId} AND condition_code IN
#{code}
ORDER BY condition_code

SELECT product_id, base_date, close_price
FROM (
    SELECT product_id, base_date, close_price
    FROM etf_history_price
    WHERE product_id = #{productId}
      AND base_date <= #{asOfDate}
    ORDER BY base_date DESC
    LIMIT #{limit}
) recent_prices
ORDER BY base_date

mapper.sql:
f.user_id = #{userId} AND ( s.status = 'SAVED' OR (s.status = 'DRAFT' AND s.expired_at > #{now}) ) AND EXISTS ( SELECT 1 FROM simulation_result history_result JOIN simulation_portfolio history_portfolio ON history_portfolio.simul_result_id = history_result.simul_result_id WHERE history_result.simul_id = s.simul_id AND history_portfolio.is_recommended = 1 GROUP BY history_result.simul_id HAVING COUNT(*) = 3 AND COUNT(DISTINCT history_portfolio.portfolio_type) = 3 )
AND s.status = #{status}
AND s.family_id = #{familyId}

mapper.select:
SELECT simul_result_id AS result_id, simul_id AS simulation_id, scenario_type, deduction_amount, taxable_amount, gift_tax, donor_required_amount, post_tax_amount, investment_principal, created_at FROM simulation_result WHERE simul_id IN
#{simulationId}
ORDER BY simul_id, simul_result_id

SELECT FROM simulation_portfolio sp JOIN simulation_result sr ON sr.simul_result_id = sp.simul_result_id WHERE sr.simul_id IN
#{simulationId}
AND sp.is_recommended = 1 ORDER BY sr.simul_id, FIELD( sp.portfolio_type, 'CONSERVATIVE', 'BALANCED', 'AGGRESSIVE' )

SELECT FROM simulation_portfolio sp JOIN simulation_result sr ON sr.simul_result_id = sp.simul_result_id WHERE sp.simul_portfolio_id IN
#{portfolioId}
ORDER BY sp.simul_portfolio_id

SELECT spr.simulation_product_id, spr.simul_portfolio_id AS portfolio_id, spr.kb_product_version_id AS product_version_id, pv.product_name, p.product_type, spr.is_selected AS selected, spr.allocated_amount, spr.applied_annual_rate AS applied_annual_rate_percent, spr.expected_future_value FROM simulation_product spr JOIN kb_product_version pv ON pv.kb_product_version_id = spr.kb_product_version_id JOIN kb_product p ON p.product_id = pv.product_id WHERE spr.simul_portfolio_id IN
#{portfolioId}
AND spr.is_selected = 1 ORDER BY spr.simul_portfolio_id, FIELD(p.product_type, 'DEPOSIT', 'SAVINGS', 'ETF'), spr.simulation_product_id

mapper.update:
UPDATE simulation_product
SET is_selected = 0,
    applied_annual_rate = #{appliedAnnualRate},
    expected_future_value = #{expectedFutureValue}
WHERE simulation_product_id = #{simulationProductId}

UPDATE simulation_product
SET is_selected = 1,
    applied_annual_rate = #{appliedAnnualRate},
    expected_future_value = #{expectedFutureValue}
WHERE simulation_product_id = #{simulationProductId}

